css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; display: grid; place-items: center; perspective: 500px; }
.loader::before { content: ''; position: absolute; width: 94%; height: 94%; border-radius: 50%; border: calc(var(--loader-size) * .045) solid var(--accent-2); transform: rotateX(75deg); animation: ring calc(var(--loader-speed) * 4) linear infinite; }
.loader span { width: 52%; height: 52%; border-radius: 50%; background: radial-gradient(circle at 38% 33%, color-mix(in srgb, #fff 40%, var(--accent)), var(--accent) 72%, color-mix(in srgb, #000 35%, var(--accent))); box-shadow: inset calc(var(--loader-size) * -.05) calc(var(--loader-size) * -.05) calc(var(--loader-size) * .1) rgba(0, 0, 0, .4); z-index: 1; }
@keyframes ring { to { transform: rotateX(75deg) rotate(360deg); } }
